+/** Theoretical (from sales) vs actual (ledger consume) use per item between two days, inclusive; difference is actual minus theoretical. */
+export function varianceReport(store, from, to) {
+  const theo = new Map();
+  const actual = new Map();
+  const add = (map, id, q) => map.set(id, Math.round(((map.get(id) ?? 0) + q) * 1000) / 1000);
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) add(theo, n.itemId, n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(actual, batch.itemId, m.qty);
+  }
+  return [...new Set([...theo.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = theo.get(itemId) ?? 0;
+      const a = actual.get(itemId) ?? 0;
+      return { itemId, theoretical: t, actual: a, difference: Math.round((a - t) * 1000) / 1000 };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
